	subroutine SquaredME(result, qext, flags)
	use global_vars
	implicit none
        integer nlegs
        parameter (nlegs = 6)
	double precision result(*), qext(nlegs,4)
	integer flags

#include "vars.h"

	double precision sumup
	external sumup

	integer Hel1, Hel2, Hel3, Hel4, Hel5, Hel6, Hel7, Hel8
	equivalence (Hel(1), Hel1)
	equivalence (Hel(2), Hel2)
	equivalence (Hel(3), Hel3)
	equivalence (Hel(4), Hel4)
	equivalence (Hel(5), Hel5)
	equivalence (Hel(6), Hel6)
	equivalence (Hel(7), Hel7)
	equivalence (Hel(8), Hel8)

	data MatSUN /1*bogus/

        integer nSUNtree
        parameter (nSUNtree = 1)
        double complex Ctree1(nSUNtree), CtreeVV(nSUNtree)
        double complex Cloop1(nSUNtree), CloopVV(nSUNtree)
        double complex ampW(2), ampZ(2), temp
        double precision S34, S56

	S = SInvariant(1,2)

	T = TInvariant(1,3)

	U = TInvariant(2,3)

C Note: qext(6,4) are the true qq -> 4l momenta
	S34 = qext(3,1)*qext(4,1) - qext(3,2)*qext(4,2) 
     &  - qext(3,3)*qext(4,3) - qext(3,4)*qext(4,4)
        S34 = S34*2
	S56 = qext(5,1)*qext(6,1) - qext(5,2)*qext(6,2) 
     &  - qext(5,3)*qext(6,3) - qext(5,4)*qext(6,4)
        S56 = S56*2

	call abbr0_s
	call abbr1_s

c	call markcache

	result(1) = 0
	result(2) = 0

	Hel1 = 1 ! anti-quark 1
	Hel2 = -Hel1 ! quark 2
	Hel5 = -1 ! lepton
	Hel6 = -Hel5
        do Hel7 = -1, 1, 2
        Hel8 = -Hel7

***[for qq->W+V*Br(W+)*Br(V)
        Ctree1(1) = 0
        Cloop1(1) = 0

        do Hel3 = hel_W_min, hel_W_max, hel_W_step ! for V1
        do Hel4 = hel_Z_min, hel_Z_max, hel_Z_step ! for V2

***[tree
	call abbr0_hel
	Ctree(1) = 0
	call born
        CtreeVV(1) = Ctree(1)
***]tree

        call decayWmll_NLO(ampW, 3, 5, 6)
        call decayZll_NLO(ampZ, 4, 7, 8)
C Ninh check
c         ampW(2) = 0 ! turn NLO W decay off
c         ampZ = 1 ! Ninh check
c          print*,"hel 5678", Hel5, Hel6, Hel7, Hel8, ampW(1), ampZ(1), CtreeVV(1)

***[tree combined
        temp = -CtreeVV(1)*ampW(1)*ampZ(1)
     &  /((S34 - CMWsq)*(S56 - CMZsq))
        Ctree1(1) = Ctree1(1) + temp
***]tree combined
***[loop combined
        temp = 
     & -CtreeVV(1)*ampW(2)*ampZ(1)
        temp = temp/((S34 - CMWsq)*(S56 - CMZsq))
        Cloop1(1) = Cloop1(1) + temp
***]loop combined
        enddo
        enddo
***]for qq->W+V*Br(W+)*Br(V)

	result(1) = result(1) + sumup(Ctree1, Ctree1)
	result(2) = result(2) + 2*sumup(Cloop1, Ctree1)

	enddo

c	call restorecache

#ifdef CHECK
	print *, 'S =', S
	print *, 'T =', T
	print *, 'U =', U

	print *, 'tree =', result(1)
	print *, 'loop =', result(2)
	stop
#endif
	end


************************************************************************

	double precision function sumup(CCloop, CCtree)
	implicit none

#include "vars.h"

	double complex CCloop(1), CCtree(1)
	double complex m

	sumup = 0

	m = 0
	m = m + CCloop(1)*MatSUN(1,1)
	sumup = sumup + DBLE(DCONJG(CCtree(1))*m)
	end
